using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class EventChecklistConfiguration:IEntityTypeConfiguration<EventChecklist>{public void Configure(EntityTypeBuilder<EventChecklist>b){b.ToTable("event_checklists");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(200);b.HasIndex(x=>x.EventId).IsUnique();b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventChecklistItemConfiguration:IEntityTypeConfiguration<EventChecklistItem>{public void Configure(EntityTypeBuilder<EventChecklistItem>b){b.ToTable("event_checklist_items");b.ConfigureBase();b.Property(x=>x.Title).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.Category).HasMaxLength(100);b.Property(x=>x.Priority).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(20);b.HasIndex(x=>x.EventId);b.HasIndex(x=>x.AssignedUserId);b.HasOne(x=>x.Checklist).WithMany(x=>x.Items).HasForeignKey(x=>x.ChecklistId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.AssignedUser).WithMany().HasForeignKey(x=>x.AssignedUserId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventStaffAssignmentConfiguration:IEntityTypeConfiguration<EventStaffAssignment>{public void Configure(EntityTypeBuilder<EventStaffAssignment>b){b.ToTable("event_staff_assignments");b.ConfigureBase();b.Property(x=>x.Role).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Notes).HasMaxLength(2000);b.HasIndex(x=>x.EventId);b.HasIndex(x=>x.UserId);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventZoneConfiguration:IEntityTypeConfiguration<EventZone>{public void Configure(EntityTypeBuilder<EventZone>b){b.ToTable("event_zones");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.Floor).HasMaxLength(100);b.HasIndex(x=>x.VenueId);b.HasOne(x=>x.Venue).WithMany().HasForeignKey(x=>x.VenueId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class BoothPlacementConfiguration:IEntityTypeConfiguration<BoothPlacement>{public void Configure(EntityTypeBuilder<BoothPlacement>b){b.ToTable("booth_placements");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.PositionNotes).HasMaxLength(2000);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.HasIndex(x=>x.EventId);b.HasIndex(x=>x.ZoneId);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Venue).WithMany().HasForeignKey(x=>x.VenueId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Zone).WithMany().HasForeignKey(x=>x.ZoneId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.AssignedOperator).WithMany().HasForeignKey(x=>x.AssignedOperatorId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventNotificationConfiguration:IEntityTypeConfiguration<EventNotification>{public void Configure(EntityTypeBuilder<EventNotification>b){b.ToTable("event_notifications");b.ConfigureBase();b.Property(x=>x.Title).HasMaxLength(200);b.Property(x=>x.Message).HasMaxLength(2000);b.Property(x=>x.Type).HasConversion<string>().HasMaxLength(30);b.HasIndex(x=>x.UserId);b.HasIndex(x=>x.EventId);}}
